#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Slice {
    /// The starting index of the slice, if any.
    pub start: Option<usize>,
    /// The (exclusive) stopping index of the slice, if any.
    pub stop: Option<usize>,
    /// The step size of the slice, if any.
    pub step: Option<usize>,
}

/// Constructs a `Slice` descriptor from the given optional start, stop, and step.
/// 
/// Panics (in debug builds) if:
/// - `step` is `Some(0)`,
/// - both `start` and `stop` are `Some` and `start > stop`.
pub fn s_(start: Option<usize>, stop: Option<usize>, step: Option<usize>) -> Slice {
    // If a step is provided, it must be strictly positive.
    debug_assert!(
        step.map_or(true, |s| s > 0),
        "step must be strictly positive if provided"
    );
    // If both start and stop are provided, start must not exceed stop.
    debug_assert!(
        match (start, stop) {
            (Some(s), Some(e)) => s <= e,
            _ => true,
        },
        "start must be <= stop if both are provided"
    );

    Slice { start, stop, step }
}

